let opening;
function open(){return opening ||= new Promise((resolve,reject)=>{const r=indexedDB.open('kanban-zen-local-v2',1);r.onupgradeneeded=()=>r.result.createObjectStore('records');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.onblocked=()=>reject(Error('Hãy đóng tab Kanban cũ để nâng cấp bộ nhớ.'));});}
export async function get(key){const db=await open();return new Promise((resolve,reject)=>{const tx=db.transaction('records'),r=tx.objectStore('records').get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
export async function set(key,value){const db=await open();return new Promise((resolve,reject)=>{const tx=db.transaction('records','readwrite');tx.objectStore('records').put(value,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}
export async function recoveries(key){const db=await open();const keys=await new Promise((resolve,reject)=>{const r=db.transaction('records').objectStore('records').getAllKeys();r.onsuccess=()=>resolve(r.result.filter(k=>typeof k==='string'&&k.startsWith(key+'-recovery-')).sort().reverse());r.onerror=()=>reject(r.error);});if(keys.length>5)await new Promise((resolve,reject)=>{const tx=db.transaction('records','readwrite');for(const k of keys.slice(5))tx.objectStore('records').delete(k);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});return keys.slice(0,5);}
export async function loadAccount(key){const existing=await get(key),raw=localStorage.getItem(key);if(!raw)return existing||null;let meta;try{meta=JSON.parse(localStorage.getItem(key+'-sync')||'{}');}catch{meta={dirty:true};}if(existing&&!meta.dirty)return existing;if(existing&&meta.dirty){await set(key+'-recovery-'+Date.now(),existing);await recoveries(key);}let parsed;try{parsed=JSON.parse(raw);}catch{return {data:null,raw,meta:{...meta,dirty:true}};}const record={data:parsed,meta,raw};if(!existing)await set(key,record);return record;}
export async function saveAccount(key,record){await set(key,record);localStorage.removeItem(key);localStorage.removeItem(key+'-sync');}
export async function usage(){return navigator.storage?.estimate?await navigator.storage.estimate():{};}
